<x-admin-layout title="Seller / Buyer Applications">
<style>
.apps{--ink:#2b1c22;--muted:#76666b;--maroon:#4a1233;--rose:#c98b6b;color:var(--ink);font-family:Inter,Arial,sans-serif}
.apps-subtitle{margin:-8px 0 22px;color:var(--muted);font-size:.9rem;line-height:1.5}
.app-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}
.app-stat,.app-card{background:#fff;border:1px solid #f0e2da;border-radius:20px;box-shadow:0 4px 18px #4a12330a}
.app-stat{padding:18px 20px;min-height:108px}.app-stat-label{color:var(--muted);font-size:.82rem;font-weight:600}.app-stat-value{display:block;margin:5px 0;font-size:1.7rem;font-weight:800;line-height:1.1}.app-stat-note{color:var(--muted);font-size:.74rem}.app-stat.pending{border-color:#efd49a}.app-stat.pending .app-stat-value{color:#805000}.app-chips{display:flex;gap:6px;margin-top:7px}.app-chip{border-radius:99px;padding:3px 8px;background:#f8ece8;color:#59474d;font-size:.68rem}
.app-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(320px,370px);gap:16px;align-items:start}.app-layout:has(.app-panel[hidden]){grid-template-columns:minmax(0,1fr)}.app-card{min-width:0;overflow:hidden}
.app-tabs{display:flex;gap:6px;padding:0 16px;border-bottom:1px solid #f0e2da;overflow:auto}.app-tab{display:flex;gap:7px;align-items:center;min-height:48px;padding:0 10px;border-bottom:3px solid transparent;color:var(--muted);font-weight:700;font-size:.82rem;text-decoration:none;white-space:nowrap}.app-tab.active{border-color:var(--maroon);color:var(--maroon)}.app-count{padding:2px 7px;border-radius:99px;background:#f6e9ed;color:var(--maroon);font-size:.7rem}
.app-toolbar{display:grid;grid-template-columns:minmax(220px,1.3fr) minmax(260px,1.3fr) minmax(120px,.75fr) minmax(120px,.75fr);gap:9px;padding:14px 16px;border-bottom:1px solid #f0e2da}.app-input{width:100%;min-height:43px;border:1px solid #ddccc6;border-radius:11px;background:#fff;color:var(--ink);padding:9px 11px;font:500 .8rem Inter,Arial,sans-serif}.app-input:focus-visible,.app-button:focus-visible,.app-tab:focus-visible{outline:3px solid #c98b6b;outline-offset:2px}.type-tabs{display:flex;gap:4px;align-items:center;overflow:auto}.type-tabs a{padding:9px 10px;border-radius:9px;text-decoration:none;color:var(--muted);font-size:.76rem;font-weight:700;white-space:nowrap}.type-tabs a.active{background:#f6e9ed;color:var(--maroon)}
.apps .sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.app-table-wrap{width:100%;overflow-x:auto}.app-table{width:100%;min-width:760px;border-collapse:collapse}.app-table th{padding:12px;background:#fbf7f5;color:#59474d;font-size:.72rem;letter-spacing:.04em;text-align:left;text-transform:uppercase;white-space:nowrap}.app-table td{padding:13px 12px;border-bottom:1px solid #f0e2da;vertical-align:middle;font-size:.8rem}.app-table tbody tr{cursor:pointer}.app-table tbody tr:hover td,.app-table tr.selected td{background:#fdf5f5}.app-person{display:flex;align-items:center;gap:9px;min-width:175px}.app-avatar{width:38px;height:38px;flex:0 0 38px;display:grid;place-items:center;border-radius:50%;background:#f5e9e7;color:var(--maroon);font-weight:800}.app-name{font-weight:750;overflow-wrap:anywhere}.app-muted{display:block;margin-top:3px;color:var(--muted);font-size:.7rem}.type-tag{display:inline-flex;padding:4px 8px;border-radius:99px;font-size:.68rem;font-weight:750}.type-tag.seller{background:#eee7f6;color:#603f85}.type-tag.buyer{background:#e5f0fb;color:#265d91}.state-tag{display:inline-flex;padding:4px 9px;border-radius:99px;font-size:.68rem;font-weight:750}.state-tag.pending{background:#fff1d2;color:#804900}.state-tag.approved{background:#e2f2e9;color:#15553a}.state-tag.rejected{background:#fce8e5;color:#8a2117}.state-tag.archived{background:#f0eaec;color:#59474d}.app-actions{display:flex;align-items:center;justify-content:flex-end;gap:5px;white-space:nowrap}.app-button{min-height:39px;padding:7px 10px;border:1px solid #e8d4ce;border-radius:10px;background:#fff;color:var(--ink);font:700 .73rem Inter,Arial,sans-serif;text-decoration:none;cursor:pointer}.app-button.primary{border-color:var(--maroon);background:var(--maroon);color:#fff}.app-button.approve{border-color:#1e6b4a;background:#1e6b4a;color:white}.app-button.reject{color:#9b2315}.app-empty{padding:32px;text-align:center;color:var(--muted)}
.app-pagination{display:flex;align-items:center;gap:7px;flex-wrap:wrap;padding:13px 16px}.app-pagination-info{margin-right:auto;color:var(--muted);font-size:.75rem}.app-page{min-width:40px;min-height:40px;display:grid;place-items:center;padding:0 9px;border:1px solid #eee0dc;border-radius:10px;color:var(--maroon);text-decoration:none;font-size:.75rem}.app-page.current{background:var(--maroon);color:white}
.app-panel{position:sticky;top:16px;max-height:calc(100vh - 32px);overflow:auto;padding:20px}.app-panel[hidden]{display:none}.app-panel-head{display:flex;justify-content:space-between;gap:10px}.app-panel h2{color:var(--maroon);font:600 1.25rem Georgia,serif;overflow-wrap:anywhere}.app-panel h3{margin:18px 0 8px;font-size:.86rem}.app-detail-box{display:grid;gap:9px;margin:15px 0;padding:14px;border-radius:14px;background:#fbf7f5}.app-detail{display:flex;justify-content:space-between;gap:12px;font-size:.76rem;color:var(--muted)}.app-detail strong{max-width:68%;color:var(--ink);text-align:right;overflow-wrap:anywhere}.app-doc{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:7px 0;padding:10px;border:1px solid #e8d4ce;border-radius:11px;font-size:.77rem}.app-checks{display:grid;gap:7px;padding-left:0;list-style:none}.app-checks li{font-size:.75rem;line-height:1.45}.app-checks .pass{color:#1e6b4a}.app-checks .warn{color:#8b4e00}.app-panel textarea{min-height:74px;resize:vertical}.reason-chips{display:flex;flex-wrap:wrap;gap:5px;margin:7px 0}.reason-chip{border:1px solid #e8d4ce;background:#fff;border-radius:99px;padding:5px 8px;color:#59474d;font-size:.68rem;cursor:pointer}.panel-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:11px}.panel-actions form .app-button{width:100%}.app-modal{position:fixed;inset:0;z-index:1000;display:grid;place-items:center;padding:20px;background:#21131dbb}.app-modal[hidden]{display:none}.app-modal-card{position:relative;max-width:min(900px,95vw);max-height:90vh;background:white;padding:18px;border-radius:18px}.app-modal img{display:block;max-width:85vw;max-height:78vh;object-fit:contain}.app-modal-close{position:absolute;right:8px;top:8px;z-index:1}
@media(max-width:1200px){.app-layout{grid-template-columns:1fr}.app-panel{position:static;max-height:none}.app-toolbar{grid-template-columns:1fr 1fr}.app-stats{gap:9px}}
@media(max-width:650px){.app-stats{grid-template-columns:1fr 1fr}.app-stat{padding:14px;min-height:96px}.app-stat-value{font-size:1.4rem}.app-toolbar{grid-template-columns:1fr;padding:12px}.app-tabs{padding:0 9px}.app-panel{padding:15px}.app-pagination-info{flex-basis:100%}}
.app-toast{position:fixed;right:20px;top:18px;z-index:1200;max-width:min(440px,calc(100vw - 32px));box-shadow:0 10px 35px #21131d33}
</style>
