        <aside class="app-card app-panel" id="reviewPanel" hidden aria-label="Application review">
            <div class="app-panel-head"><div><span class="app-muted" id="panelType">Application review</span><h2 id="panelName"></h2><span class="app-muted" id="panelApplied"></span></div><button class="app-button" type="button" id="closePanel" aria-label="Close review">Close</button></div>
