<div class="app-modal" id="idPreviewModal" hidden role="dialog" aria-modal="true" aria-label="Buyer identity document preview"><div class="app-modal-card"><button class="app-button app-modal-close" type="button" id="closeIdPreview">Close</button><img id="idPreviewImage" alt="Uploaded identity document"></div></div>
<script>
(()=>{const panel=document.getElementById('reviewPanel'),content=document.getElementById('panelContent'),modal=document.getElementById('idPreviewModal'),preview=document.getElementById('idPreviewImage'),csrf=document.querySelector('meta[name="csrf-token"]')?.content||'';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function showReview(button){const d=button.dataset,buyer=d.kind==='buyer',pending=d.status==='pending',check=(ok,text)=>`<li class="${ok?'pass':'warn'}">${ok?'✓':'!'} ${text}</li>`,doc=d.idAvailable==='1'?`<div class="app-doc"><span>${buyer?esc(d.idType||'Valid ID'): 'Valid ID'} ${buyer?'':'(seller)'}</span><button class="app-button" type="button" data-view-id data-url="${esc(d.idUrl)}" data-mime="${esc(d.idMime)}">View</button></div>`:`<div class="app-doc">Valid ID <span class="app-muted">Not uploaded or unavailable</span></div>`,permit=!buyer?(d.permitAvailable==='1'?`<div class="app-doc"><span>Business permit</span><a class="app-button" href="${esc(d.permitUrl)}" target="_blank" rel="noopener">View</a></div>`:'<div class="app-doc">Business permit <span class="app-muted">Not uploaded</span></div>'):'';
document.getElementById('panelName').textContent=d.name;document.getElementById('panelType').textContent=`${buyer?'Buyer':'Seller'} application · ${d.status}`;document.getElementById('panelApplied').textContent=`Applied ${d.applied}`;
let details=buyer?`<div class="app-detail"><span>Full name</span><strong>${esc(d.owner)}</strong></div><div class="app-detail"><span>Email</span><strong>${esc(d.email)}</strong></div><div class="app-detail"><span>Phone</span><strong>${esc(d.phone||'Not provided')}</strong></div><div class="app-detail"><span>Date of birth</span><strong>${esc(d.dob||'Not provided')} (${esc(d.age||'—')} years)</strong></div><div class="app-detail"><span>Full address</span><strong>${esc(d.address||'Incomplete')}</strong></div>`:`<div class="app-detail"><span>Owner</span><strong>${esc(d.owner)}</strong></div><div class="app-detail"><span>Email</span><strong>${esc(d.email)}</strong></div><div class="app-detail"><span>Phone</span><strong>${esc(d.phone||'Not provided')}</strong></div><div class="app-detail"><span>Sells</span><strong>${esc(d.category||'Not provided')}</strong></div>`;
let checks=buyer?[check(d.emailVerified==='1','Email verified.'),check(d.idAvailable==='1','Valid ID uploaded and available to view.'),check(d.ageOk==='1','Age 18 or above.'),check(d.addressOk==='1','Delivery address complete.'),check(d.duplicatePhone!=='1','No duplicate account with the same phone number.'),`<li class="app-muted">Joined ${esc(d.applied)} · ${esc(d.orders)} orders. This buyer cannot log in or check out until approved.</li>`]:[check(d.emailVerified==='1','Email verified.'),check(d.idAvailable==='1'&&d.permitAvailable==='1','Required documents available.'),`<li>Shop details: ${esc(d.description||'Not provided')}</li>`];
content.innerHTML=`<div class="app-detail-box">${details}</div>${buyer?'':`<h3>About the shop</h3><p>${esc(d.description||'No shop description provided.')}</p>`}<h3>Documents</h3>${doc}${permit}<h3>Quick checks</h3><ul class="app-checks">${checks.join('')}</ul>${d.status==='rejected'?`<p><strong>Previous rejection:</strong> ${esc(d.rejection||'Not recorded')}</p>`:''}${pending?`<h3>Reason if rejecting</h3><div class="reason-chips">${['Incomplete details','Could not verify identity','Duplicate account','Under 18'].map(r=>`<button class="reason-chip" type="button" data-reason="${esc(r)}">${esc(r)}</button>`).join('')}</div><form id="rejectAppForm" method="POST" action="${esc(d.rejectUrl)}"><input type="hidden" name="_token" value="${esc(csrf)}"><textarea class="app-input" name="reason" maxlength="1000" required placeholder="Enter a reason for rejecting this application"></textarea><div class="panel-actions"><button class="app-button reject" type="submit">Reject</button><button class="app-button approve" type="button" data-approve>Approve ${buyer?'buyer':'seller'}</button></div></form><form id="approveAppForm" method="POST" action="${esc(d.reviewUrl)}" hidden><input type="hidden" name="_token" value="${esc(csrf)}"></form><form id="archiveAppForm" method="POST" action="${esc(d.archiveUrl)}" hidden><input type="hidden" name="_token" value="${esc(csrf)}"></form><button type="button" class="app-button" data-archive>Archive</button>`:''}`;
panel.hidden=false;document.querySelectorAll('[data-application-row]').forEach(r=>r.classList.toggle('selected',r.dataset.id===button.closest('tr').dataset.id&&r.dataset.type===button.closest('tr').dataset.type));content.querySelectorAll('[data-reason]').forEach(b=>b.addEventListener('click',()=>{const ta=content.querySelector('textarea[name=reason]');ta.value=b.dataset.reason;ta.focus()}));content.querySelector('[data-approve]')?.addEventListener('click',()=>{if(confirm(`Approve this ${buyer?'buyer':'seller'} application?`))document.getElementById('approveAppForm').requestSubmit()});content.querySelector('[data-archive]')?.addEventListener('click',()=>{if(confirm('Archive this application?'))document.getElementById('archiveAppForm').requestSubmit()});content.querySelector('[data-view-id]')?.addEventListener('click',e=>{const url=e.currentTarget.dataset.url;if(e.currentTarget.dataset.mime==='application/pdf'){window.open(url,'_blank','noopener');return}preview.src=url;modal.hidden=false});content.querySelector('#rejectAppForm')?.addEventListener('submit',e=>{if(!e.currentTarget.reason.value.trim()){e.preventDefault();e.currentTarget.reason.focus()}});panel.scrollIntoView({behavior:'smooth',block:'nearest'})}
document.querySelectorAll('[data-review]').forEach(b=>b.addEventListener('click',()=>showReview(b)));document.querySelectorAll('[data-review-reject]').forEach(b=>b.addEventListener('click',()=>{showReview(b.closest('tr').querySelector('[data-review]'));setTimeout(()=>content.querySelector('textarea[name=reason]')?.focus(),0)}));document.querySelectorAll('[data-application-row]').forEach(r=>{r.addEventListener('click',e=>{if(e.target.closest('button,form,a'))return;showReview(r.querySelector('[data-review]'))});r.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target===r)showReview(r.querySelector('[data-review]'))})});document.getElementById('closePanel').addEventListener('click',()=>panel.hidden=true);document.getElementById('closeIdPreview').addEventListener('click',()=>{modal.hidden=true;preview.removeAttribute('src')});modal.addEventListener('click',e=>{if(e.target===modal){modal.hidden=true;preview.removeAttribute('src')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){panel.hidden=true;modal.hidden=true;preview.removeAttribute('src')}});document.querySelectorAll('#applicationPeriod,#applicationSort').forEach(el=>el.addEventListener('change',()=>document.getElementById('applicationsFilter').requestSubmit()));})();
</script>
</x-admin-layout>
